/* The searchable catalogue.
 *
 * `assets/data/sources.json` is generated by `tools/export_catalogue.py`
 * straight from the corpus the app ships, so this page cannot drift from what
 * is actually in the library.
 *
 * Everything is client-side: 687 records is roughly 700 KB of JSON, which is one
 * request and a few milliseconds of filtering. A search API would be a server to
 * run and pay for, for a dataset that changes when the corpus is rebuilt.
 */
(function () {
  "use strict";

  var PAGE = 48; // cards rendered per batch

  var q = document.getElementById("q");
  var clear = document.getElementById("clear");
  var fTradition = document.getElementById("f-tradition");
  var fType = document.getElementById("f-type");
  var fCollection = document.getElementById("f-collection");
  var fSort = document.getElementById("f-sort");
  var reset = document.getElementById("reset");
  var results = document.getElementById("results");
  var countEl = document.getElementById("count");
  var emptyEl = document.getElementById("empty");
  var moreBtn = document.getElementById("more");

  var all = [];
  var shown = [];
  var rendered = 0;

  /* --------------------------------------------------------------- utils -- */

  /** Everything from the JSON is untrusted markup as far as the DOM is
   *  concerned — titles carry ampersands, excerpts carry angle brackets. */
  function esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function chars(n) {
    if (n >= 1e6) return (n / 1e6).toFixed(1).replace(/\.0$/, "") + "M characters";
    if (n >= 1e3) return Math.round(n / 1e3) + "K characters";
    return n + " characters";
  }

  function host(url) {
    try {
      return new URL(url).hostname.replace(/^www\./, "");
    } catch (e) {
      return "source";
    }
  }

  /* ------------------------------------------------------------ indexing -- */

  /** One lowercased haystack per record, built once. Rebuilding it inside the
   *  keystroke handler was the difference between instant and visibly laggy. */
  function index(s) {
    return [
      s.title,
      s.author,
      s.tradition,
      s.type,
      s.translator,
      s.edition,
      s.excerpt,
      s.collections.map(function (c) {
        return c.name;
      }).join(" "),
    ]
      .join(" ")
      .toLowerCase();
  }

  function matches(s, terms) {
    for (var i = 0; i < terms.length; i++) {
      if (s._hay.indexOf(terms[i]) === -1) return false;
    }
    return true;
  }

  /* ------------------------------------------------------------- filters -- */

  function apply() {
    var terms = q.value.toLowerCase().trim().split(/\s+/).filter(Boolean);
    var tradition = fTradition.value;
    var type = fType.value;
    var collection = fCollection.value;

    shown = all.filter(function (s) {
      if (tradition && s.tradition !== tradition) return false;
      if (type && s.type !== type) return false;
      if (
        collection &&
        !s.collections.some(function (c) {
          return c.id === collection;
        })
      )
        return false;
      return !terms.length || matches(s, terms);
    });

    var sort = fSort.value;
    shown.sort(function (a, b) {
      if (sort === "largest") return b.chars - a.chars;
      if (sort === "smallest") return a.chars - b.chars;
      if (sort === "title") return a.title.localeCompare(b.title);
      return a.author.localeCompare(b.author) || a.title.localeCompare(b.title);
    });

    clear.hidden = !q.value;
    countEl.textContent =
      shown.length === all.length
        ? all.length.toLocaleString() + " works"
        : shown.length.toLocaleString() +
          " of " +
          all.length.toLocaleString() +
          " works";
    emptyEl.hidden = shown.length > 0;

    results.textContent = "";
    rendered = 0;
    draw();
    remember();
  }

  function draw() {
    var slice = shown.slice(rendered, rendered + PAGE);
    var frag = document.createDocumentFragment();

    slice.forEach(function (s) {
      var li = document.createElement("li");
      li.className = "src";

      var meta = [];
      if (s.translator) meta.push(["Translator", s.translator]);
      if (s.edition) meta.push(["Edition", s.edition]);
      if (s.corroboration) meta.push(["Corroborated", s.corroboration]);

      li.innerHTML =
        '<h2 class="src__title">' +
        esc(s.title) +
        "</h2>" +
        '<p class="src__author">' +
        esc(s.author) +
        (s.dates ? ' <span class="src__dates">· ' + esc(s.dates) + "</span>" : "") +
        "</p>" +
        '<div class="src__tags">' +
        '<span class="tag">' +
        esc(s.tradition) +
        "</span>" +
        '<span class="tag tag--type">' +
        esc(s.type) +
        "</span>" +
        (s.bundled
          ? '<span class="tag tag--bundled">Built in</span>'
          : s.collections
              // A collection often carries its tradition's name — "Catholic"
              // the tradition and "Catholic" the download — and showing both
              // reads as a rendering bug rather than as two different facts.
              .filter(function (c) {
                return c.name !== s.tradition;
              })
              .slice(0, 2)
              .map(function (c) {
                return '<span class="tag tag--type">' + esc(c.name) + "</span>";
              })
              .join("")) +
        "</div>" +
        (s.excerpt
          ? '<p class="src__excerpt">' + esc(s.excerpt) + "</p>"
          : "") +
        (meta.length
          ? '<dl class="src__meta">' +
            meta
              .map(function (m) {
                return (
                  "<div><dt>" + esc(m[0]) + "</dt><dd>" + esc(m[1]) + "</dd></div>"
                );
              })
              .join("") +
            "</dl>"
          : "") +
        '<div class="src__foot">' +
        '<span class="src__size">' +
        s.units.toLocaleString() +
        " sections · " +
        chars(s.chars) +
        "</span>" +
        (s.url
          ? '<a class="src__link" href="' +
            esc(s.url) +
            '" rel="noopener noreferrer" target="_blank">' +
            esc(host(s.url)) +
            " ↗</a>"
          : "") +
        "</div>";

      frag.appendChild(li);
    });

    results.appendChild(frag);
    rendered += slice.length;
    moreBtn.hidden = rendered >= shown.length;
    moreBtn.textContent =
      "Show " +
      Math.min(PAGE, shown.length - rendered).toLocaleString() +
      " more of " +
      (shown.length - rendered).toLocaleString();
  }

  /* ----------------------------------------------------------- url state -- */

  /** Keep the query in the address bar so a filtered view can be linked and
   *  survives a reload. `replaceState` rather than `pushState`: typing should
   *  not fill the back button with one entry per keystroke. */
  function remember() {
    var p = new URLSearchParams();
    if (q.value) p.set("q", q.value);
    if (fTradition.value) p.set("tradition", fTradition.value);
    if (fType.value) p.set("type", fType.value);
    if (fCollection.value) p.set("collection", fCollection.value);
    if (fSort.value !== "author") p.set("sort", fSort.value);
    var qs = p.toString();
    history.replaceState(null, "", qs ? "?" + qs : location.pathname);
  }

  function restore() {
    var p = new URLSearchParams(location.search);
    q.value = p.get("q") || "";
    fTradition.value = p.get("tradition") || "";
    fType.value = p.get("type") || "";
    fCollection.value = p.get("collection") || "";
    fSort.value = p.get("sort") || "author";
  }

  /* ----------------------------------------------------------- populate -- */

  function options(select, values) {
    values.forEach(function (v) {
      var o = document.createElement("option");
      o.value = v.value;
      o.textContent = v.label;
      select.appendChild(o);
    });
  }

  fetch("assets/data/sources.json")
    .then(function (r) {
      if (!r.ok) throw new Error("HTTP " + r.status);
      return r.json();
    })
    .then(function (data) {
      all = data.sources;
      all.forEach(function (s) {
        s._hay = index(s);
      });

      document.querySelectorAll("[data-stat]").forEach(function (el) {
        var v = data.totals[el.dataset.stat];
        if (v != null) el.textContent = v.toLocaleString();
      });

      var traditions = {};
      var types = {};
      all.forEach(function (s) {
        traditions[s.tradition] = (traditions[s.tradition] || 0) + 1;
        types[s.type] = (types[s.type] || 0) + 1;
      });

      function byCount(map) {
        return Object.keys(map)
          .sort(function (a, b) {
            return map[b] - map[a] || a.localeCompare(b);
          })
          .map(function (k) {
            return { value: k, label: k + " (" + map[k] + ")" };
          });
      }

      options(fTradition, byCount(traditions));
      options(fType, byCount(types));
      options(
        fCollection,
        data.collections
          .slice()
          .sort(function (a, b) {
            return a.name.localeCompare(b.name);
          })
          .map(function (c) {
            return { value: c.id, label: c.name + " (" + c.sources + ")" };
          })
      );

      q.placeholder =
        "Search " + all.length + " works by title, author or opening line…";

      restore();
      apply();
    })
    .catch(function (err) {
      countEl.textContent =
        "The catalogue could not be loaded (" +
        err.message +
        "). If you are opening this file directly, serve the folder over HTTP instead.";
    });

  /* ------------------------------------------------------------- events -- */

  // Debounced: filtering 687 records is cheap, but rebuilding 48 cards on every
  // keystroke of a fast typist is not.
  var timer;
  q.addEventListener("input", function () {
    clearTimeout(timer);
    timer = setTimeout(apply, 120);
  });

  [fTradition, fType, fCollection, fSort].forEach(function (el) {
    el.addEventListener("change", apply);
  });

  clear.addEventListener("click", function () {
    q.value = "";
    q.focus();
    apply();
  });

  reset.addEventListener("click", function () {
    q.value = "";
    fTradition.value = "";
    fType.value = "";
    fCollection.value = "";
    fSort.value = "author";
    apply();
  });

  moreBtn.addEventListener("click", draw);

  /* ---------------------------------------------------------- the form --- */

  var form = document.getElementById("request-form");
  var status = document.getElementById("form-status");

  if (form) {
    form.addEventListener("submit", function (e) {
      e.preventDefault();
      var btn = form.querySelector("button[type=submit]");
      btn.disabled = true;
      status.className = "form__status";
      status.textContent = "Sending…";

      fetch("https://formspree.io/f/mldbgwbb", {
        method: "POST",
        body: new FormData(form),
        headers: { Accept: "application/json" },
      })
        .then(function (r) {
          if (!r.ok) throw new Error();
          form.reset();
          status.className = "form__status form__status--ok";
          status.textContent = "Sent — thank you. I read every one of these.";
        })
        .catch(function () {
          status.className = "form__status form__status--err";
          // Deliberately not offering an email address as a fallback — the one
          // in the form config is a reply-to, not a published inbox, and
          // inventing a contact address is worse than admitting the failure.
          status.innerHTML =
            'That did not send. You can <a href="https://github.com/SpencerSmithSite/council/issues" rel="noopener">open an issue on GitHub</a> instead.';
        })
        .finally(function () {
          btn.disabled = false;
        });
    });
  }
})();
